/* ====== Root / Layout ====== */
:root {
  --bg-0: #020e2e;
  --bg-1: #061538;
  --card: rgba(23, 33, 62, 0.88);
  --card-border: rgba(255, 255, 255, 0.06);
  --muted: rgba(255, 255, 255, 0.62);
  --text: rgba(255, 255, 255, 0.92);

  --accent: #2e6bff;
  --accent-2: #3ca4ff;

  --danger: #ff6565;
  --success: #22c55e;

  --shadow: 0 28px 70px rgba(0, 0, 0, 0.42);
  --radius: 12px;
  --radius-lg: 14px;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(900px 420px at 50% 30%, rgba(255,255,255,0.06), rgba(255,255,255,0) 60%),
    radial-gradient(1000px 600px at 50% 100%, rgba(60,164,255,0.06), rgba(60,164,255,0) 55%),
    linear-gradient(180deg, var(--bg-0) 0%, var(--bg-1) 100%);
}

/* ====== App Container ====== */
.hu-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ====== Header ====== */
.hu-header {
  height: 64px;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hu-logo {
  display: block;
  height: 34px;            /* increased size */
  width: auto;
  object-fit: contain;
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.25));
}

.hu-logo--right {
  height: 32px;            /* slightly smaller on right */
  opacity: 0.95;
}

/* ====== Main / Views ====== */
.hu-main {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 18px 18px 10px;
}

.hu-view {
  width: 100%;
  display: grid;
  place-items: center;
}

.hu-view--hidden {
  display: none;
}

/* ====== Card ====== */
.hu-card {
  width: min(820px, 92vw);
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 34px 40px;
  backdrop-filter: blur(8px);
}

.hu-card--success {
  width: min(720px, 92vw);
  padding: 44px 40px;
  text-align: center;
}

.hu-title {
  margin: 0 0 8px;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.hu-subtitle {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.55;
}

/* ====== Field / Label ====== */
.hu-field {
  margin-top: 8px;
}

.hu-label {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255,255,255,0.82);
  margin-bottom: 10px;
}

.hu-required {
  color: var(--danger);
  margin-left: 2px;
}

.hu-help-row {
  margin-top: 10px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.hu-help {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
}

.hu-error {
  font-size: 12px;
  color: var(--danger);
  min-height: 16px;
  text-align: right;
  white-space: pre-line;
}

/* ====== Dropzone ====== */
.hu-drop {
  border: 2px dashed rgba(255,255,255,0.18);
  border-radius: 10px;
  background: rgba(2, 14, 46, 0.18);
  padding: 26px 18px;
  display: grid;
  place-items: center;
  text-align: center;
  gap: 10px;
  transition: border-color 140ms ease, background 140ms ease, transform 140ms ease;
  outline: none;
}

.hu-drop:hover {
  border-color: rgba(60,164,255,0.42);
  background: rgba(2, 14, 46, 0.26);
}

.hu-drop.is-dragover {
  border-color: rgba(60,164,255,0.78);
  background: rgba(46,107,255,0.10);
  transform: translateY(-1px);
}

.hu-drop.is-error {
  border-color: rgba(255,101,101,0.65);
  background: rgba(255,101,101,0.06);
}

.hu-drop__icon {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.75);
}

.hu-drop__title {
  font-size: 14px;
  font-weight: 600;
  color: rgba(255,255,255,0.88);
}

.hu-drop__or {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
  margin-top: -2px;
}

/* ====== Buttons ====== */
.hu-btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 11px 14px;
  font-size: 14px;
  font-weight: 650;
  cursor: pointer;
  transition: transform 120ms ease, opacity 120ms ease, background 120ms ease, border-color 120ms ease;
}

.hu-btn:active {
  transform: translateY(1px);
}

.hu-btn--ghost {
  background: rgba(23, 33, 62, 0.18);
  color: var(--accent-2);
  border-color: rgba(60,164,255,0.35);
  padding: 10px 16px;
}

.hu-btn--ghost:hover {
  background: rgba(23, 33, 62, 0.28);
  border-color: rgba(60,164,255,0.55);
}

.hu-btn--primary {
  background: var(--accent);
  color: white;
}

.hu-btn--primary:hover {
  opacity: 0.94;
}

.hu-btn--full {
  width: 100%;
  padding: 13px 14px;
  border-radius: 9px;
  font-size: 15px;
}

.hu-btn.is-busy {
  opacity: 0.75;
  cursor: progress;
  pointer-events: none;
}

/* ====== Files List ====== */
.hu-files {
  margin-top: 18px;
}

.hu-files__hdr {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 10px;
  color: rgba(255,255,255,0.85);
}

.hu-files__list {
  display: grid;
  gap: 10px;
}

.hu-fileRow {
  background: rgba(2, 14, 46, 0.35);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 12px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.hu-fileIcon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(46,107,255,0.12);
  border: 1px solid rgba(46,107,255,0.22);
  color: rgba(255,255,255,0.85);
  flex: 0 0 auto;
}

.hu-fileMeta {
  flex: 1 1 auto;
  min-width: 0;
}

.hu-fileName {
  font-size: 13px;
  font-weight: 700;
  color: rgba(255,255,255,0.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hu-fileSize {
  margin-top: 2px;
  font-size: 12px;
  color: rgba(255,255,255,0.45);
}

.hu-fileRemove {
  flex: 0 0 auto;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.85);
  width: 34px;
  height: 34px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  display: grid;
  place-items: center;
  transition: background 120ms ease, border-color 120ms ease;
}

.hu-fileRemove:hover {
  background: rgba(255,255,255,0.10);
  border-color: rgba(255,255,255,0.22);
}

.hu-sep {
  margin: 18px 0 18px;
  height: 1px;
  background: rgba(255,255,255,0.08);
}

/* ====== Success View ====== */
.hu-successIcon {
  display: grid;
  place-items: center;
  margin: 6px auto 16px;
}

.hu-successIcon__ring {
  width: 54px;
  height: 54px;
  border-radius: 999px;
  background: rgba(34,197,94,0.18);
  border: 1px solid rgba(34,197,94,0.35);
  display: grid;
  place-items: center;
  box-shadow: 0 12px 30px rgba(34,197,94,0.12);
}

.hu-contactCard {
  margin: 22px auto 18px;
  width: min(420px, 100%);
  padding: 14px 14px;
  border-radius: 10px;
  background: rgba(2, 14, 46, 0.25);
  border: 1px solid rgba(255,255,255,0.08);
}

.hu-contactCard__title {
  font-size: 12px;
  color: rgba(255,255,255,0.55);
  margin-bottom: 8px;
}

.hu-contactCard__email {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--accent-2);
  font-weight: 700;
}

.hu-contactCard__email:hover {
  opacity: 0.9;
}

.hu-linkBtn {
  border: none;
  background: transparent;
  color: rgba(255,255,255,0.60);
  cursor: pointer;
  font-weight: 650;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 6px;
}

.hu-linkBtn:hover {
  color: rgba(255,255,255,0.82);
}

.hu-linkBtn__icon {
  font-size: 16px;
}

/* ====== Footer ====== */
.hu-footer {
  height: 60px;
  display: grid;
  place-items: center;
  font-size: 12px;
  color: rgba(255,255,255,0.28);
}

/* ====== Toast ====== */
.hu-toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 9999;
  max-width: min(420px, calc(100vw - 36px));
}

.hu-toast--hidden {
  display: none;
}

.hu-toast__inner {
  background: rgba(2, 14, 46, 0.92);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 12px;
  box-shadow: 0 18px 55px rgba(0,0,0,0.45);
  padding: 12px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  backdrop-filter: blur(10px);
}

.hu-toast__msg {
  flex: 1 1 auto;
  font-size: 13px;
  color: rgba(255,255,255,0.88);
}

.hu-toast__action {
  border: 1px solid rgba(60,164,255,0.35);
  background: rgba(46,107,255,0.16);
  color: rgba(255,255,255,0.92);
  border-radius: 10px;
  padding: 8px 10px;
  cursor: pointer;
  font-weight: 700;
  font-size: 12px;
}

.hu-toast__action:hover {
  border-color: rgba(60,164,255,0.55);
}

.hu-toast__close {
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.9);
  width: 30px;
  height: 30px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
}

/* ====== Responsive ====== */
@media (max-width: 640px) {
  .hu-card { padding: 26px 18px; }
  .hu-header { padding: 0 14px; }
  .hu-logo { height: 30px; }
  .hu-logo--right { height: 28px; }
}

