template.css:
/* ====== Root / Layout ====== */
:root {
  --bg-0: #020e2e;
  --bg-1: #061538;
  --card: rgba(23, 33, 62, 0.88);
  --card-border: rgba(255, 255, 255, 0.06);
  --muted: rgba(255, 255, 255, 0.62);
  --text: rgba(255, 255, 255, 0.92);

  --accent: #2e6bff;
  --accent-2: #3ca4ff;

  --danger: #ff6565;
  --success: #22c55e;

  --shadow: 0 28px 70px rgba(0, 0, 0, 0.42);
  --radius: 12px;
  --radius-lg: 14px;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(900px 420px at 50% 30%, rgba(255,255,255,0.06), rgba(255,255,255,0) 60%),
    radial-gradient(1000px 600px at 50% 100%, rgba(60,164,255,0.06), rgba(60,164,255,0) 55%),
    linear-gradient(180deg, var(--bg-0) 0%, var(--bg-1) 100%);
}

/* ====== App Container ====== */
.hu-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ====== Header ====== */
.hu-header {
  height: 64px;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hu-logo {
  display: block;
  height: 34px;            /* increased size */
  width: auto;
  object-fit: contain;
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.25));
}

.hu-logo--right {
  height: 32px;            /* slightly smaller on right */
  opacity: 0.95;
}

/* ====== Main / Views ====== */
.hu-main {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 18px 18px 10px;
}

.hu-view {
  width: 100%;
  display: grid;
  place-items: center;
}

.hu-view--hidden {
  display: none;
}

/* ====== Card ====== */
.hu-card {
  width: min(820px, 92vw);
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 34px 40px;
  backdrop-filter: blur(8px);
}

.hu-card--success {
  width: min(720px, 92vw);
  padding: 44px 40px;
  text-align: center;
}

.hu-title {
  margin: 0 0 8px;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.hu-subtitle {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.55;
}

/* ====== Field / Label ====== */
.hu-field {
  margin-top: 8px;
}

.hu-label {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255,255,255,0.82);
  margin-bottom: 10px;
}

.hu-required {
  color: var(--danger);
  margin-left: 2px;
}

.hu-help-row {
  margin-top: 10px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.hu-help {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
}

.hu-error {
  font-size: 12px;
  color: var(--danger);
  min-height: 16px;
  text-align: right;
  white-space: pre-line;
}

/* ====== Dropzone ====== */
.hu-drop {
  border: 2px dashed rgba(255,255,255,0.18);
  border-radius: 10px;
  background: rgba(2, 14, 46, 0.18);
  padding: 26px 18px;
  display: grid;
  place-items: center;
  text-align: center;
  gap: 10px;
  transition: border-color 140ms ease, background 140ms ease, transform 140ms ease;
  outline: none;
}

.hu-drop:hover {
  border-color: rgba(60,164,255,0.42);
  background: rgba(2, 14, 46, 0.26);
}

.hu-drop.is-dragover {
  border-color: rgba(60,164,255,0.78);
  background: rgba(46,107,255,0.10);
  transform: translateY(-1px);
}

.hu-drop.is-error {
  border-color: rgba(255,101,101,0.65);
  background: rgba(255,101,101,0.06);
}

.hu-drop__icon {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.75);
}

.hu-drop__title {
  font-size: 14px;
  font-weight: 600;
  color: rgba(255,255,255,0.88);
}

.hu-drop__or {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
  margin-top: -2px;
}

/* ====== Buttons ====== */
.hu-btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 11px 14px;
  font-size: 14px;
  font-weight: 650;
  cursor: pointer;
  transition: transform 120ms ease, opacity 120ms ease, background 120ms ease, border-color 120ms ease;
}

.hu-btn:active {
  transform: translateY(1px);
}

.hu-btn--ghost {
  background: rgba(23, 33, 62, 0.18);
  color: var(--accent-2);
  border-color: rgba(60,164,255,0.35);
  padding: 10px 16px;
}

.hu-btn--ghost:hover {
  background: rgba(23, 33, 62, 0.28);
  border-color: rgba(60,164,255,0.55);
}

.hu-btn--primary {
  background: var(--accent);
  color: white;
}

.hu-btn--primary:hover {
  opacity: 0.94;
}

.hu-btn--full {
  width: 100%;
  padding: 13px 14px;
  border-radius: 9px;
  font-size: 15px;
}

.hu-btn.is-busy {
  opacity: 0.75;
  cursor: progress;
  pointer-events: none;
}

/* ====== Files List ====== */
.hu-files {
  margin-top: 18px;
}

.hu-files__hdr {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 10px;
  color: rgba(255,255,255,0.85);
}

.hu-files__list {
  display: grid;
  gap: 10px;
}

.hu-fileRow {
  background: rgba(2, 14, 46, 0.35);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 12px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.hu-fileIcon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(46,107,255,0.12);
  border: 1px solid rgba(46,107,255,0.22);
  color: rgba(255,255,255,0.85);
  flex: 0 0 auto;
}

.hu-fileMeta {
  flex: 1 1 auto;
  min-width: 0;
}

.hu-fileName {
  font-size: 13px;
  font-weight: 700;
  color: rgba(255,255,255,0.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hu-fileSize {
  margin-top: 2px;
  font-size: 12px;
  color: rgba(255,255,255,0.45);
}

.hu-fileRemove {
  flex: 0 0 auto;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.85);
  width: 34px;
  height: 34px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  display: grid;
  place-items: center;
  transition: background 120ms ease, border-color 120ms ease;
}

.hu-fileRemove:hover {
  background: rgba(255,255,255,0.10);
  border-color: rgba(255,255,255,0.22);
}

.hu-sep {
  margin: 18px 0 18px;
  height: 1px;
  background: rgba(255,255,255,0.08);
}

/* ====== Success View ====== */
.hu-successIcon {
  display: grid;
  place-items: center;
  margin: 6px auto 16px;
}

.hu-successIcon__ring {
  width: 54px;
  height: 54px;
  border-radius: 999px;
  background: rgba(34,197,94,0.18);
  border: 1px solid rgba(34,197,94,0.35);
  display: grid;
  place-items: center;
  box-shadow: 0 12px 30px rgba(34,197,94,0.12);
}

.hu-contactCard {
  margin: 22px auto 18px;
  width: min(420px, 100%);
  padding: 14px 14px;
  border-radius: 10px;
  background: rgba(2, 14, 46, 0.25);
  border: 1px solid rgba(255,255,255,0.08);
}

.hu-contactCard__title {
  font-size: 12px;
  color: rgba(255,255,255,0.55);
  margin-bottom: 8px;
}

.hu-contactCard__email {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--accent-2);
  font-weight: 700;
}

.hu-contactCard__email:hover {
  opacity: 0.9;
}

.hu-linkBtn {
  border: none;
  background: transparent;
  color: rgba(255,255,255,0.60);
  cursor: pointer;
  font-weight: 650;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 6px;
}

.hu-linkBtn:hover {
  color: rgba(255,255,255,0.82);
}

.hu-linkBtn__icon {
  font-size: 16px;
}

/* ====== Footer ====== */
.hu-footer {
  height: 60px;
  display: grid;
  place-items: center;
  font-size: 12px;
  color: rgba(255,255,255,0.28);
}

/* ====== Toast ====== */
.hu-toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 9999;
  max-width: min(420px, calc(100vw - 36px));
}

.hu-toast--hidden {
  display: none;
}

.hu-toast__inner {
  background: rgba(2, 14, 46, 0.92);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 12px;
  box-shadow: 0 18px 55px rgba(0,0,0,0.45);
  padding: 12px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  backdrop-filter: blur(10px);
}

.hu-toast__msg {
  flex: 1 1 auto;
  font-size: 13px;
  color: rgba(255,255,255,0.88);
}

.hu-toast__action {
  border: 1px solid rgba(60,164,255,0.35);
  background: rgba(46,107,255,0.16);
  color: rgba(255,255,255,0.92);
  border-radius: 10px;
  padding: 8px 10px;
  cursor: pointer;
  font-weight: 700;
  font-size: 12px;
}

.hu-toast__action:hover {
  border-color: rgba(60,164,255,0.55);
}

.hu-toast__close {
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.9);
  width: 30px;
  height: 30px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
}

/* ====== Responsive ====== */
@media (max-width: 640px) {
  .hu-card { padding: 26px 18px; }
  .hu-header { padding: 0 14px; }
  .hu-logo { height: 30px; }
  .hu-logo--right { height: 28px; }
}

template.js:
(() => {
  'use strict';

  const GLOBAL = (window.HenceUpload = window.HenceUpload || {});
  GLOBAL.__initCount = (GLOBAL.__initCount || 0) + 1;
  GLOBAL.__uiSubmitting = !!GLOBAL.__uiSubmitting;

  const MAX_BYTES = 35 * 1024 * 1024;
  const ACCEPT_MIME = 'application/pdf';
  const ACCEPT_EXT_RE = /\.pdf$/i;
  const EVENT_NAME = 'documentsSubmitted';
  const SUPPORT_EMAIL = 'document-upload@hence.ai';
  const SUCCESS_SUBTITLE_TEXT =
    'Thank you for submitting your documents. We have received your files and will process them shortly.';
  const FAILURE_SUBTITLE_DEFAULT = 'We could not upload your documents. Please try again.';

  const KEY_DOC_STATE = 'hu_documents';
  const KEY_LOGO_HENCE = 'v_app_hence_logo';
  const KEY_LOGO_COMPANY = 'v_company_logo';
  const KEY_UPLOAD_ERROR = 'v_upload_error';
  const KEY_UPLOAD_FAILED = 'v_upload_failed';
  const KEY_UPLOAD_DONE = 'v_upload_done';
  const KEY_UPLOAD_TOTAL = 'v_upload_total';
  const KEY_UPLOAD_SUBMISSION = 'v_upload_submissionId';
  const KEY_PDF_UPLOAD = 'v_pdfUpload';

  const Slate = window.SlateFunctions || {};
  const DEBUG =
    /[?&]huDebug=1\b/.test(String(window.location?.search || '')) ||
    !!(Slate.getState?.()?.v_debug_upload);

  const $ = (id) => document.getElementById(id);

  const el = {
    app: $('huApp'),
    main: document.querySelector('.hu-main'),
    henceLogo: $('huHenceLogo'),
    companyLogo: $('huCompanyLogo'),

    uploadView: $('huUploadView'),
    successView: $('huSuccessView'),
    failureView: $('huFailureView'),

    successSubtitle: null,
    failureSubtitle: $('huFailureSubtitle'),

    drop: $('huDrop'),
    fileInput: $('huFileInput'),
    browseBtn: $('huBrowseBtn'),
    submitBtn: $('huSubmitBtn'),

    emailField: $('huEmailField'),
    emailInput: $('huEmailInput'),

    error: $('huError'),
    maxFileSize: $('huMaxFileSize'),

    filesWrap: $('huFilesWrap'),
    filesHdr: $('huFilesHdr'),
    filesList: $('huFilesList'),

    uploadMoreBtn: $('huUploadMoreBtn'),
    failureUploadMoreBtn: $('huFailureUploadMoreBtn'),

    toast: $('huToast'),
    toastMsg: $('huToastMsg'),
    toastAction: $('huToastAction'),
    toastClose: $('huToastClose'),
  };

  let debugPanel = null;
  function ensureDebugPanel() {
    if (!DEBUG || debugPanel) return;
    debugPanel = document.createElement('div');
    debugPanel.style.position = 'fixed';
    debugPanel.style.left = '12px';
    debugPanel.style.bottom = '12px';
    debugPanel.style.width = '420px';
    debugPanel.style.maxHeight = '40vh';
    debugPanel.style.overflow = 'auto';
    debugPanel.style.padding = '10px';
    debugPanel.style.zIndex = '999999';
    debugPanel.style.font =
      '12px/1.35 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    debugPanel.style.background = 'rgba(0,0,0,0.75)';
    debugPanel.style.color = '#fff';
    debugPanel.style.border = '1px solid rgba(255,255,255,0.15)';
    debugPanel.style.borderRadius = '8px';
    debugPanel.innerHTML = '<div style="opacity:.8;margin-bottom:6px">HENCE UPLOAD DEBUG</div>';
    document.body.appendChild(debugPanel);
  }

  function log(...args) {
    if (!DEBUG) return;
    try {
      console.log('[HENCE UPLOAD]', ...args);
    } catch {}
    ensureDebugPanel();
    if (!debugPanel) return;
    const line = document.createElement('div');
    line.style.whiteSpace = 'pre-wrap';
    line.textContent = args.map((a) => (typeof a === 'string' ? a : JSON.stringify(a))).join(' ');
    debugPanel.appendChild(line);
    debugPanel.scrollTop = debugPanel.scrollHeight;
  }

  function getState() {
    try {
      return Slate.getState?.() || {};
    } catch {
      return {};
    }
  }

  function setStateKey(key, value) {
    try {
      if (typeof Slate.setState === 'function') {
        if (Slate.setState.length >= 2) Slate.setState(key, value);
        else Slate.setState({ [key]: value });
        return true;
      }
    } catch (e) {
      log('setStateKey error', e);
    }
    return false;
  }

  function triggerEvent(name, payload) {
    try {
      Slate.triggerEvent?.(name, payload);
      return true;
    } catch (e) {
      log('triggerEvent error', e);
      return false;
    }
  }

  function updateHuDocuments(partial) {
    const st = getState();
    const cur = st[KEY_DOC_STATE];
    if (!cur || typeof cur !== 'object') {
      log(`State "${KEY_DOC_STATE}" missing or not an object.`);
      return false;
    }
    const allowed = Object.keys(cur);
    const next = { ...cur, ...partial };
    const filtered = {};
    for (const k of allowed) filtered[k] = next[k];
    return setStateKey(KEY_DOC_STATE, filtered);
  }

  Object.assign(GLOBAL, { getState, updateHuDocuments });

  function decodeEntities(raw) {
    const s = String(raw ?? '').trim();
    if (!s) return '';
    const t = document.createElement('textarea');
    t.innerHTML = s;
    return (t.value || '').trim();
  }

  function looksLikeSvgMarkup(s) {
    return /^\s*<svg[\s>]/i.test(String(s || ''));
  }

  function svgToDataUri(svgText) {
    const svg = String(svgText || '').trim();
    if (!svg) return '';
    const encoded = encodeURIComponent(svg)
      .replace(/%0A/g, '')
      .replace(/%20/g, ' ')
      .replace(/%3D/g, '=')
      .replace(/%3A/g, ':')
      .replace(/%2F/g, '/');
    return `data:image/svg+xml;charset=utf-8,${encoded}`;
  }

  function looksLikeBareBase64(s) {
    const v = String(s || '').trim();
    if (!v || v.startsWith('data:') || v.startsWith('blob:') || v.startsWith('<')) return false;
    if (v.length < 128) return false;
    return /^[A-Za-z0-9+/=\s]+$/.test(v) && !/^https?:\/\//i.test(v);
  }

  function coerceImgSrc(raw) {
    const v0 = decodeEntities(raw);
    if (!v0) return '';
    if (v0.startsWith('data:image/')) return v0;
    if (v0.startsWith('blob:')) return v0;
    if (looksLikeSvgMarkup(v0)) return svgToDataUri(v0);
    if (looksLikeBareBase64(v0)) return `data:image/png;base64,${v0.replace(/\s+/g, '')}`;
    if (/^https?:\/\//i.test(v0)) return '';
    const m = v0.match(/<img[^>]+src=["']([^"']+)["']/i);
    if (m?.[1]) return coerceImgSrc(m[1]);
    return '';
  }

  function setLogo(imgEl, raw) {
    if (!imgEl) return;
    const src = coerceImgSrc(raw);
    if (!src) {
      imgEl.style.display = 'none';
      imgEl.removeAttribute('src');
      return;
    }
    imgEl.style.display = '';
    imgEl.src = src;
  }

  function applyLogos() {
    const st = getState();
    setLogo(el.henceLogo, st[KEY_LOGO_HENCE]);
    setLogo(el.companyLogo, st[KEY_LOGO_COMPANY]);
  }

  function ensureDynamicStyles() {
    if (document.getElementById('hu-dynamic-styles')) return;
    const style = document.createElement('style');
    style.id = 'hu-dynamic-styles';
    style.textContent = `
      .hu-input {
        width: 100%;
        border: 1px solid rgba(255,255,255,0.18);
        background: rgba(2,14,46,0.28);
        color: rgba(255,255,255,0.92);
        border-radius: 9px;
        padding: 12px 13px;
        outline: none;
        font-size: 14px;
      }
      .hu-input:focus {
        border-color: rgba(60,164,255,0.65);
        box-shadow: 0 0 0 3px rgba(60,164,255,0.16);
      }
      .hu-input::placeholder { color: rgba(255,255,255,0.42); }
    `;
    document.head.appendChild(style);
  }

  function setSuccessSubtitleText() {
    if (!el.successSubtitle && el.successView) {
      el.successSubtitle = el.successView.querySelector('.hu-subtitle');
    }
    if (el.successSubtitle) {
      el.successSubtitle.textContent = SUCCESS_SUBTITLE_TEXT;
    }
  }

  function ensureEmailField() {
    if (el.emailInput) return;
    const uploadCard = el.uploadView?.querySelector('.hu-card--upload');
    if (!uploadCard) return;

    const wrap = document.createElement('div');
    wrap.className = 'hu-field';
    wrap.id = 'huEmailField';
    wrap.innerHTML = `
      <div class="hu-label">
        Email <span class="hu-required">*</span>
      </div>
      <input id="huEmailInput" class="hu-input" type="email" inputmode="email" autocomplete="email" placeholder="name@company.com" />
      <div class="hu-help" style="margin-top:10px;">We will use this email for follow-up on your submission.</div>
    `;

    const sep = uploadCard.querySelector('.hu-sep');
    uploadCard.insertBefore(wrap, sep || null);

    el.emailField = $('huEmailField');
    el.emailInput = $('huEmailInput');
  }

  function stripMailtoLinks() {
    const nodes = document.querySelectorAll('a.hu-contactCard__email[href^="mailto:"]');
    nodes.forEach((a) => {
      a.removeAttribute('href');
      a.setAttribute('role', 'text');
      a.style.cursor = 'default';
      a.style.textDecoration = 'none';
    });
  }

  function ensureFailureView() {
    if (el.failureView) return;
    if (!el.main) return;

    const section = document.createElement('section');
    section.className = 'hu-view hu-view--hidden';
    section.id = 'huFailureView';
    section.innerHTML = `
      <div class="hu-card hu-card--success">
        <div class="hu-successIcon" aria-hidden="true">
          <div class="hu-successIcon__ring" style="background: rgba(255,101,101,0.18); border: 1px solid rgba(255,101,101,0.38); box-shadow: 0 12px 30px rgba(255,101,101,0.14);">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <path d="M7 7l10 10M17 7L7 17" stroke="#FFECEC" stroke-width="2.4" stroke-linecap="round"/>
            </svg>
          </div>
        </div>

        <h1 class="hu-title">Upload Failed</h1>
        <p class="hu-subtitle" id="huFailureSubtitle">${FAILURE_SUBTITLE_DEFAULT}</p>

        <div class="hu-contactCard">
          <div class="hu-contactCard__title">Have questions?</div>
          <div class="hu-contactCard__email" role="text">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M4 6h16v12H4V6z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
              <path d="M4 7l8 6 8-6" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
            </svg>
            ${SUPPORT_EMAIL}
          </div>
        </div>

        <button class="hu-linkBtn" id="huFailureUploadMoreBtn" type="button">
          <span class="hu-linkBtn__icon" aria-hidden="true">←</span>
          Back to Upload
        </button>
      </div>
    `;

    el.main.appendChild(section);
    el.failureView = section;
    el.failureSubtitle = $('huFailureSubtitle');
    el.failureUploadMoreBtn = $('huFailureUploadMoreBtn');

    if (el.failureUploadMoreBtn && el.failureUploadMoreBtn.dataset.wired !== '1') {
      el.failureUploadMoreBtn.dataset.wired = '1';
      el.failureUploadMoreBtn.addEventListener('click', resetAll);
    }

    stripMailtoLinks();
  }

  function showError(msg) {
    if (!el.error) return;
    el.error.textContent = msg ? String(msg) : '';
    el.drop?.classList.toggle('is-error', !!msg);
  }

  function clearError() {
    showError('');
  }

  function normalizeEmail(v) {
    return String(v ?? '').trim();
  }

  function isValidEmail(v) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
  }

  function mountToastToBody() {
    if (!el.toast) return;
    try {
      if (el.toast.parentElement !== document.body) document.body.appendChild(el.toast);
      el.toast.hidden = false;
      if (el.toast.style.display === 'none') el.toast.style.display = '';
      if (!el.toast.getAttribute('role')) el.toast.setAttribute('role', 'status');
      el.toast.setAttribute('aria-live', 'polite');
      if (!el.toast.style.zIndex) el.toast.style.zIndex = '999999';
    } catch (e) {
      log('mountToastToBody error', e);
    }
  }

  let toastTimer = null;
  function showToast(message) {
    if (!el.toast || !el.toastMsg) return;
    mountToastToBody();
    el.toastMsg.textContent = message || 'Done.';
    el.toast.hidden = false;
    el.toast.style.display = '';
    el.toast.setAttribute('aria-hidden', 'false');
    el.toast.classList.remove('hu-toast--hidden');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(hideToast, 6500);
  }

  function hideToast() {
    if (!el.toast) return;
    el.toast.classList.add('hu-toast--hidden');
    el.toast.setAttribute('aria-hidden', 'true');
    clearTimeout(toastTimer);
    toastTimer = null;
  }

  function showUploadView() {
    el.successView?.classList.add('hu-view--hidden');
    el.failureView?.classList.add('hu-view--hidden');
    el.uploadView?.classList.remove('hu-view--hidden');
  }

  function showSuccessView() {
    setSuccessSubtitleText();
    el.uploadView?.classList.add('hu-view--hidden');
    el.failureView?.classList.add('hu-view--hidden');
    el.successView?.classList.remove('hu-view--hidden');
  }

  function showFailureView(message) {
    ensureFailureView();
    if (el.failureSubtitle) {
      const msg = String(message || '').trim();
      el.failureSubtitle.textContent = msg ? `${msg}` : FAILURE_SUBTITLE_DEFAULT;
    }
    el.uploadView?.classList.add('hu-view--hidden');
    el.successView?.classList.add('hu-view--hidden');
    el.failureView?.classList.remove('hu-view--hidden');
  }

  let submitBtnBaseText = null;
  function setSubmitBusy(isBusy, textOverride) {
    if (!el.submitBtn) return;
    if (submitBtnBaseText == null) submitBtnBaseText = el.submitBtn.textContent || 'Submit Documents';
    el.submitBtn.classList.toggle('is-busy', !!isBusy);
    el.submitBtn.textContent = textOverride != null ? String(textOverride) : submitBtnBaseText;
  }

  function restoreSubmitText() {
    if (!el.submitBtn) return;
    if (submitBtnBaseText == null) submitBtnBaseText = el.submitBtn.textContent || 'Submit Documents';
    el.submitBtn.classList.remove('is-busy');
    el.submitBtn.textContent = submitBtnBaseText;
  }

  function sameSubmission(st) {
    const active = String(GLOBAL.__activeSubmissionId || '');
    if (!active) return true;

    const sid1 = String(st[KEY_UPLOAD_SUBMISSION] || '');
    const sid2 = String(st[KEY_PDF_UPLOAD]?.submissionId || '');

    if (sid1 && sid1 === active) return true;
    if (sid2 && sid2 === active) return true;
    if (!sid1 && !sid2) return true;

    return false;
  }

  function refreshUploadUiFromState() {
    const st = getState();
    if (!sameSubmission(st)) return;

    const failed = !!st[KEY_UPLOAD_FAILED];
    const errMsg = String(st[KEY_UPLOAD_ERROR] || '').trim();
    const done = Number(st[KEY_UPLOAD_DONE] || 0);
    const total = Number(st[KEY_UPLOAD_TOTAL] || 0);

    if (failed) {
      const msg = errMsg || 'Upload failed. Please try again.';
      showError(msg);
      showToast(msg);
      updateHuDocuments({ status: 'error', error: msg });
      restoreSubmitText();
      showFailureView(msg);
      GLOBAL.__uiSubmitting = false;
      return;
    }

    if (total > 0) {
      showUploadView();
      const cappedDone = Math.min(done, total);
      // setSubmitBusy(true, `Uploading… (${cappedDone}/${total})`);
      setSubmitBusy(true, `Uploading…`);

      if (done >= total) {
        clearError();
        updateHuDocuments({ status: 'submitted', error: '' });
        restoreSubmitText();
        showSuccessView();
        showToast('Uploaded successfully.');
        GLOBAL.__uiSubmitting = false;
      }
    }
  }

  let files = [];

  function fmtSize(bytes) {
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
  }

  function fmtLimit(bytes) {
    const mb = bytes / (1024 * 1024);
    if (!Number.isFinite(mb) || mb <= 0) return '0 MB';
    return `${mb.toFixed(mb >= 10 ? 0 : 2)} MB`;
  }

  function totalSize(list) {
    return (Array.isArray(list) ? list : []).reduce((sum, f) => sum + Number(f?.size || 0), 0);
  }

  function totalSizeError(totalBytes) {
    // return `Total selected files (${fmtLimit(totalBytes)}) exceed ${fmtLimit(MAX_BYTES)}. Please remove some files and try again.`;

    return `Total selected files (${fmtLimit(totalBytes)}) exceed 30MB. Please remove some files and try again.`;
  }

  function escapeHtml(s) {
    return String(s || '')
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#039;');
  }

  function isPdf(file) {
    if (!file) return false;
    const typeOk = (file.type || '').toLowerCase() === ACCEPT_MIME;
    const nameOk = ACCEPT_EXT_RE.test(file.name || '');
    return typeOk || nameOk;
  }

  function validateIncoming(incoming) {
    const accepted = [];
    const errors = [];
    for (const f of incoming) {
      if (!isPdf(f)) {
        errors.push(`"${f.name}" is not a PDF.`);
        continue;
      }
      if (f.size > MAX_BYTES) {
        // errors.push(`"${f.name}" exceeds ${fmtLimit(MAX_BYTES)}.`);
        errors.push(`"${f.name}" exceeds 30MB.`);
        continue;
      }
      accepted.push(f);
    }
    return { accepted, errors };
  }

  function dedupe(nextFiles) {
    const key = (f) => `${f.name}::${f.size}::${f.lastModified}`;
    const seen = new Set(files.map(key));
    const out = [...files];
    for (const f of nextFiles) {
      const k = key(f);
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(f);
    }
    return out;
  }

  function renderFiles() {
    if (!el.filesWrap || !el.filesHdr || !el.filesList) return;

    const count = files.length;
    if (!count) {
      el.filesWrap.hidden = true;
      el.filesHdr.textContent = '';
      el.filesList.innerHTML = '';
      return;
    }

    el.filesWrap.hidden = false;
    el.filesHdr.textContent = `Attached Files (${count})`;
    el.filesList.innerHTML = '';

    files.forEach((f, idx) => {
      const row = document.createElement('div');
      row.className = 'hu-fileRow';
      row.innerHTML = `
        <div class="hu-fileIcon" aria-hidden="true">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
            <path d="M7 3h7l3 3v15H7V3z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
            <path d="M14 3v4h4" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="hu-fileMeta">
          <div class="hu-fileName" title="${escapeHtml(f.name)}">${escapeHtml(f.name)}</div>
          <div class="hu-fileSize">${fmtSize(f.size)}</div>
        </div>
        <button class="hu-fileRemove" type="button" aria-label="Remove ${escapeHtml(f.name)}">×</button>
      `;
      row.querySelector('.hu-fileRemove')?.addEventListener('click', () => {
        files.splice(idx, 1);
        renderFiles();
        if (!files.length) clearError();
      });
      el.filesList.appendChild(row);
    });
  }

  function addFiles(fileList) {
    const incoming = Array.from(fileList || []);
    if (!incoming.length) return;
    const { accepted, errors } = validateIncoming(incoming);
    const nextFiles = dedupe(accepted);
    const nextTotal = totalSize(nextFiles);
    if (nextTotal > MAX_BYTES) {
      const allErrors = [...errors, totalSizeError(nextTotal)];
      showError(allErrors.join('\n'));
      return;
    }
    files = nextFiles;
    renderFiles();
    if (errors.length) showError(errors.join('\n'));
    else clearError();
  }

  function readAsDataUrl(file) {
    return new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onerror = () => reject(new Error(`Failed to read "${file?.name || 'file'}"`));
      r.onload = () => resolve(String(r.result || ''));
      r.readAsDataURL(file);
    });
  }

  async function onSubmitClick() {
    clearError();
    const submitterEmail = normalizeEmail(el.emailInput?.value);

		if (!isValidEmail(submitterEmail)) {
			showError('Please enter a valid email address.');
			GLOBAL.__uiSubmitting = false;
			return;
		}

    if (!files.length) {
      showError('Please attach at least one PDF.');
      GLOBAL.__uiSubmitting = false;
      return;
    }

    const { errors } = validateIncoming(files);
    if (errors.length) {
      showError(errors.join('\n'));
      GLOBAL.__uiSubmitting = false;
      return;
    }

    const total = totalSize(files);
    if (total > MAX_BYTES) {
      showError(totalSizeError(total));
      GLOBAL.__uiSubmitting = false;
      return;
    }

    setSubmitBusy(true, 'Preparing…');

    try {
      const meta = files.map((f) => ({
        name: f.name,
        size: f.size,
        type: f.type || ACCEPT_MIME,
        lastModified: f.lastModified || null,
      }));

      updateHuDocuments({
        status: 'submitting',
        files: meta,
        uploaded: [],
        error: '',
      });

      const out = [];
      for (let i = 0; i < files.length; i++) {
        setSubmitBusy(true, `Reading… (${i + 1}/${files.length})`);
        const dataUrl = await readAsDataUrl(files[i]);
        out.push({ ...meta[i], dataUrl });
      }

      const submissionId =
        crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;

      GLOBAL.__activeSubmissionId = submissionId;

      const payload = {
        submissionId,
        uploadedAt: new Date().toISOString(),
        includeFileBytes: true,
        submitterEmail,
        files: out,
      };

      const ok = triggerEvent(EVENT_NAME, JSON.stringify(payload));
      if (!ok) throw new Error('Failed to trigger documentsSubmitted event.');

      updateHuDocuments({ status: 'uploading', error: '' });
      setSubmitBusy(true, `Uploading… (0/${files.length})`);
      showToast('Upload started…');
      log('Triggered documentsSubmitted payload', payload);
    } catch (e) {
      const msg = `Submit failed: ${e?.message || e}`;
      showError(msg);
      updateHuDocuments({ status: 'error', error: msg });
      restoreSubmitText();
      showToast(msg);
      showFailureView(msg);
      log(msg);
      GLOBAL.__activeSubmissionId = null;
      GLOBAL.__uiSubmitting = false;
    }
  }

  function resetAll() {
    files = [];
    if (el.fileInput) el.fileInput.value = '';
    if (el.emailInput) el.emailInput.value = '';
    renderFiles();
    clearError();
    showUploadView();
    restoreSubmitText();

    if (el.failureSubtitle) {
      el.failureSubtitle.textContent = FAILURE_SUBTITLE_DEFAULT;
    }

    GLOBAL.__activeSubmissionId = null;
    GLOBAL.__uiSubmitting = false;

    updateHuDocuments({
      status: 'idle',
      files: [],
      uploaded: [],
      error: '',
    });

    setStateKey(KEY_UPLOAD_ERROR, '');
    setStateKey(KEY_UPLOAD_FAILED, false);
    setStateKey(KEY_UPLOAD_DONE, 0);
    setStateKey(KEY_UPLOAD_TOTAL, 0);
    setStateKey(KEY_UPLOAD_SUBMISSION, '');

    showToast('Ready to upload more.');
  }

  function wireDnD() {
    if (!el.drop) return;
    if (el.drop.dataset.wired === '1') return;
    el.drop.dataset.wired = '1';

    const prevent = (e) => {
      e.preventDefault();
      e.stopPropagation();
    };

    ['dragenter', 'dragover'].forEach((evt) => {
      el.drop.addEventListener(evt, (e) => {
        prevent(e);
        el.drop.classList.add('is-dragover');
      });
    });

    ['dragleave', 'drop'].forEach((evt) => {
      el.drop.addEventListener(evt, (e) => {
        prevent(e);
        el.drop.classList.remove('is-dragover');
      });
    });

    el.drop.addEventListener('drop', (e) => {
      const dt = e.dataTransfer;
      if (dt?.files?.length) addFiles(dt.files);
    });

    el.drop.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        el.fileInput?.click();
      }
    });
  }

  function wireBrowse() {
    if (el.browseBtn && el.browseBtn.dataset.wired !== '1') {
      el.browseBtn.dataset.wired = '1';
      el.browseBtn.addEventListener('click', () => el.fileInput?.click());
    }
    if (el.fileInput && el.fileInput.dataset.wired !== '1') {
      el.fileInput.dataset.wired = '1';
      el.fileInput.addEventListener('change', () => addFiles(el.fileInput.files));
    }
  }

  function wireSubmit() {
    if (!el.submitBtn) return;
    if (el.submitBtn.dataset.wired === '1') return;
    el.submitBtn.dataset.wired = '1';

    el.submitBtn.addEventListener('click', async () => {
      if (GLOBAL.__uiSubmitting) return;
      GLOBAL.__uiSubmitting = true;
      try {
        await onSubmitClick();
      } catch {
        GLOBAL.__uiSubmitting = false;
      }
    });
  }

  function wireActions() {
    if (el.uploadMoreBtn && el.uploadMoreBtn.dataset.wired !== '1') {
      el.uploadMoreBtn.dataset.wired = '1';
      el.uploadMoreBtn.addEventListener('click', resetAll);
    }
    if (el.failureUploadMoreBtn && el.failureUploadMoreBtn.dataset.wired !== '1') {
      el.failureUploadMoreBtn.dataset.wired = '1';
      el.failureUploadMoreBtn.addEventListener('click', resetAll);
    }
    if (el.toastAction && el.toastAction.dataset.wired !== '1') {
      el.toastAction.dataset.wired = '1';
      el.toastAction.addEventListener('click', () => {
        hideToast();
        resetAll();
      });
    }
    if (el.toastClose && el.toastClose.dataset.wired !== '1') {
      el.toastClose.dataset.wired = '1';
      el.toastClose.addEventListener('click', hideToast);
    }
  }

  function init() {
    if (!el.uploadView || !el.successView || !el.drop || !el.fileInput) {
      log('Missing required DOM nodes.');
      return;
    }

    ensureDynamicStyles();
    ensureEmailField();
    ensureFailureView();
    stripMailtoLinks();
    setSuccessSubtitleText();
    if (el.maxFileSize) el.maxFileSize.textContent = fmtLimit(MAX_BYTES);
    // document.getElementById('huEmailField').remove();

    mountToastToBody();

    applyLogos();
    Slate.watch?.(KEY_LOGO_HENCE, applyLogos);
    Slate.watch?.(KEY_LOGO_COMPANY, applyLogos);

    Slate.watch?.(KEY_UPLOAD_ERROR, refreshUploadUiFromState);
    Slate.watch?.(KEY_UPLOAD_FAILED, refreshUploadUiFromState);
    Slate.watch?.(KEY_UPLOAD_DONE, refreshUploadUiFromState);
    Slate.watch?.(KEY_UPLOAD_TOTAL, refreshUploadUiFromState);
    Slate.watch?.(KEY_PDF_UPLOAD, refreshUploadUiFromState);
    Slate.watch?.(KEY_UPLOAD_SUBMISSION, refreshUploadUiFromState);

    wireDnD();
    wireBrowse();
    wireSubmit();
    wireActions();

    showUploadView();
    renderFiles();

    if (el.submitBtn && submitBtnBaseText == null) {
      submitBtnBaseText = el.submitBtn.textContent || 'Submit Documents';
    }

    refreshUploadUiFromState();
    log('init ok', { initCount: GLOBAL.__initCount });
  }

  if (document.readyState !== 'loading') init();
  else document.addEventListener('DOMContentLoaded', init);
})();

