q_upload_pdf.failure.functionBody:
const err = {{slQueryError}} ?? {};

const statusCandidates = [
  err?.parameters?.statusCode,
  err?.parameters?.status,
  err?.statusCode,
  err?.status,
  err?.httpStatusCode,
  err?.httpStatus,
  err?.response?.status,
  err?.response?.statusCode,
  err?.response?.data?.status,
  err?.response?.data?.statusCode
];

let status = 0;
for (const v of statusCandidates) {
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) {
    status = n;
    break;
  }
}

const detail = String(
  err?.parameters?.message ??
  err?.response?.data?.message ??
  err?.response?.message ??
  err?.message ??
  err?.errorName ??
  ""
).trim();

if (status === 413) return "Upload failed: total selected files exceed the 30 MB limit. Please remove files and try again.";
if (status === 400) return `Upload failed (400): invalid payload. ${detail || "Check selected files and retry."}`;
if (status === 401 || status === 403) return `Upload failed (${status}): authorization error.`;
if (status === 404) return "Upload failed (404): upload channel/endpoint not found.";
if (status === 415) return "Upload failed (415): unsupported media type.";
if (status === 429) return "Upload failed (429): too many requests. Retry shortly.";
if (status >= 500) return `Upload failed (${status}): server error. Please retry.`;
if (status > 0) return `Upload failed (${status}). ${detail || ""}`.trim();

return detail || "Upload failed: unknown error.";

const err = {{slQueryError}} ?? {};
const candidates = [
  err?.parameters?.statusCode,
  err?.parameters?.status,
  err?.statusCode,
  err?.status,
  err?.httpStatusCode,
  err?.httpStatus,
  err?.response?.status,
  err?.response?.statusCode,
  err?.response?.data?.status,
  err?.response?.data?.statusCode
];

for (const v of candidates) {
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) return n;
}
return 0;

v_pdfUpload.changed.functionBody:
const sid = String({{v_pdfUpload}}?.submissionId ?? "").trim();
const lastTriggered = String({{v_uploadTrigger}} ?? "").trim();
if (!sid) return {{slDisableAction}};
if (sid === lastTriggered) return {{slDisableAction}};
if ({{f_upload_content}} == null) return {{slDisableAction}};

const sid = String({{v_pdfUpload}}?.submissionId ?? "").trim();
if (!sid) return String({{v_uploadTrigger}} ?? "");
if ({{f_upload_content}} == null) return String({{v_uploadTrigger}} ?? "");
return sid;

const c = {{f_upload_content}};
if (c != null) return "";

const rawMax = {{v_max_upload_bytes}};
const parsedMax = Number(String(rawMax ?? "").replace(/[,_\s]/g, ""));
const MAX_BYTES = Number.isFinite(parsedMax) && parsedMax > 0 ? parsedMax : 35 * 1024 * 1024;

const p = {{v_pdfUpload}} ?? {};
const files = Array.isArray(p?.files) ? p.files : [];

if (!files.length) return "Please attach at least one PDF.";

const totalBytes = files.reduce((sum, f) => sum + Number(f?.size ?? 0), 0);
if (totalBytes > MAX_BYTES) {
  const mb = (n) => `${(n / (1024 * 1024)).toFixed(2)} MB`;
  return `Total selected files are ${mb(totalBytes)}. Maximum allowed is ${mb(MAX_BYTES)}.`;
}

return "Empty or invalid file.";

w_file_upload.custom.documentsSubmitted.functionBody:
let ev = {{slEventValue}};

if (typeof ev === "string") {
  try { ev = JSON.parse(ev); } catch { return {{v_pdfUpload}} ?? {}; }
}

if (!ev || typeof ev !== "object") return {{v_pdfUpload}} ?? {};

const prev = {{v_pdfUpload}} ?? {};
const submissionId = String(ev?.submissionId ?? "").trim();

if (!submissionId) return prev;
if (submissionId === String(prev?.submissionId ?? "").trim()) return prev;

const rawFiles = Array.isArray(ev?.files) ? ev.files : [];

const files = rawFiles
  .map((f) => {
    const base64FromField = typeof f?.base64 === "string" ? f.base64 : "";
    const dataUrl = typeof f?.dataUrl === "string" ? f.dataUrl : "";
    const base64 = base64FromField || (dataUrl.includes(",") ? dataUrl.slice(dataUrl.indexOf(",") + 1) : dataUrl);

    return {
      name: String(f?.name ?? ""),
      type: String(f?.type ?? "application/pdf"),
      size: Number(f?.size ?? 0),
      lastModified: Number(f?.lastModified ?? 0),
      base64
    };
  })
  .filter((f) => f.base64.length > 0 && f.size > 0);

if (!files.length) return prev;

return {
  submissionId,
  uploadedAt: String(ev?.uploadedAt ?? ""),
  submitterEmail: String(ev?.submitterEmail ?? "").trim(),
  files
};

let ev = {{slEventValue}};
if (typeof ev === "string") { try { ev = JSON.parse(ev); } catch { return String({{v_upload_submissionId}} ?? ""); } }

const sid = String(ev?.submissionId ?? "");

return sid || String({{v_upload_submissionId}} ?? "");

functionInfos.body:
return {
  type: "blobUploadToDataset",
  blobUploadToDataset: {
    channel: "fortuna-document-upload-new-dataset",
    expiry: "2026-04-30T23:59:59Z",
    count: 1
  }
};

const datasetRid = String({{v_datasetRid}} ?? "");
const maxBlobSize = Number({{v_max_upload_bytes}} ?? (35 * 1024 * 1024));

return {
  configuration: {
    dataset: datasetRid,
    maxBlobSize,
    options: {
      type: "json",
      json: {}
    }
  }
};

const rawMax = {{v_max_upload_bytes}};
const parsedMax = Number(String(rawMax ?? "").replace(/[,_\s]/g, ""));
const MAX_BYTES = Number.isFinite(parsedMax) && parsedMax > 0 ? parsedMax : 35 * 1024 * 1024;

const batch = {{v_pdfUpload}} ?? {};
const submissionId = String(batch?.submissionId ?? "").trim();
const email = String(batch?.submitterEmail ?? "").trim();

if (!submissionId) return null;

const files = Array.isArray(batch?.files) ? batch.files : [];
if (!files.length) return null;

let totalBytes = 0;
const outFiles = [];

for (const f of files) {
  const base64 = typeof f?.base64 === "string" ? f.base64 : "";
  const size = Number(f?.size ?? 0);

  if (!base64) return null;
  if (!(size > 0 && size <= MAX_BYTES)) return null;

  totalBytes += size;

  outFiles.push({
    fileName: String(f?.name ?? ""),
    mimeType: String(f?.type ?? "application/pdf"),
    sizeBytes: String(size),
    lastModified: String(f?.lastModified ?? 0),
    base64
  });
}

if (totalBytes > MAX_BYTES) return null;

return {
  submissionId,
  email,
  uploadedAt: String(batch?.uploadedAt ?? ""),
  files: outFiles
};
